.quote {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  margin: 0;
  min-inline-size: 0;
}

/* The mark is a glyph, not a rail: a coloured bar down the side is decoration
 * the system does not use, and the icon says the same thing in one place. */
.quote-mark { color: var(--primary-accent); }

.quote-body {
  margin: 0;
  font-size: var(--font-md);
  line-height: var(--leading-snug);
  color: var(--foreground);
  text-wrap: pretty;
}
.quote[data-size="lg"] .quote-body { font-size: var(--font-lg); }

/* THE SOURCE READS WITH THE ROLE, ON THE LAST LINE OF THE ATTRIBUTION.
 *
 * Three positions were tried on one card. `center` (as shipped) floated it in
 * the gutter between the name and the role with nothing to align to. `baseline`
 * is worse and not fixable from here: measured in Chromium, a flex container
 * exports its FIRST item's baseline, and an <Identity>'s first item is the
 * avatar, whose baseline is its bottom edge — the source dropped 17px. Aligned
 * to the TOP it landed on the name's line and read as part of the name.
 *
 * The last line is where it belongs, because that is the line it continues:
 * "Head of Safety · Site 14" is one fact about one person, and the role and the
 * place are the same size and the same colour already (owner, 23.08). Aligning
 * to the end puts them on one line without Quote reaching inside whatever `by`
 * happens to be. */
.quote-by {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: var(--space-2);
  font-size: var(--font-sm);
  color: var(--muted-foreground);
}
.quote-source::before { content: "·"; margin-inline-end: var(--space-2); }

import "./Quote.css";
import type { ReactNode } from "react";
import { cn } from "../lib/cn";
import { Icon } from "../Icon";

type Size = "md" | "lg";

type Props = {
  /** The words. Somebody else's, which is the whole point of the component. */
  children: ReactNode;
  /** Who said it: an <Identity>, or a name and a role. Required, because an
   *  unattributed quote proves nothing — it is copy we wrote about ourselves. */
  by: ReactNode;
  /** Where it comes from: a company, a report, a date. */
  source?: ReactNode;
  /** How much of the page the quote is ASKING FOR. `md` sits inside something else that carries
   *  on around it; `lg` is the pull quote a section is built around, and a page gets one.
   */
  size?: Size;
  className?: string;
};

/** A quotation with its attribution, in real <figure>/<blockquote> semantics —
 *  a testimonial, a finding quoted from a report, a line from an interview.
 *  For the system's own voice use ordinary text; this is for someone else's. 
 *
 * Copy: the words are the speaker's, unedited; trimming a quote to fit is how a
 * testimonial stops being one. `by` is a person, `source` is where they
 * said it or what they do — an unattributed quote is copy, not evidence.
 */
export function Quote({ children, by, source, size, className }: Props) {
  return (
    <figure className={cn("quote", className)} data-size={size}>
      <Icon name="quote" size="md" className="quote-mark" aria-hidden="true" />
      <blockquote className="quote-body">{children}</blockquote>
      <figcaption className="quote-by">
        {by}
        {source && <span className="quote-source">{source}</span>}
      </figcaption>
    </figure>
  );
}
